from __future__ import annotations

import subprocess
import sys
from pathlib import Path

_HOOK_TEMPLATE = """\
#!/bin/sh
# Vantage post-commit hook — enqueues a commit report draft.
# Generated by: vantage-ghost hook install
# Remove this file to disable.
"{python}" -m ghost_daemon commit-report --repo "$(git rev-parse --show-toplevel)" &
"""


def install(repo_path: Path) -> Path:
    """Write (or overwrite) the Vantage post-commit hook. Returns the hook path."""
    hooks_dir = repo_path / ".git" / "hooks"
    if not hooks_dir.exists():
        raise FileNotFoundError(f"No .git/hooks directory in {repo_path}")

    hook_path = hooks_dir / "post-commit"
    python_posix = Path(sys.executable).as_posix()
    hook_path.write_text(_HOOK_TEMPLATE.format(python=python_posix), encoding="utf-8")
    try:
        hook_path.chmod(0o755)
    except NotImplementedError:
        pass  # Windows — git-for-windows handles executable bits
    return hook_path


def is_installed(repo_path: Path) -> bool:
    hook_path = repo_path / ".git" / "hooks" / "post-commit"
    if not hook_path.exists():
        return False
    try:
        return "ghost_daemon" in hook_path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return False


def get_head_commit(repo_path: Path) -> dict:
    """Return metadata dict for HEAD in repo_path."""
    def _git(*args) -> str:
        return subprocess.check_output(
            ["git", *args], cwd=repo_path, text=True, timeout=10, stderr=subprocess.DEVNULL
        ).strip()

    try:
        sha = _git("rev-parse", "HEAD")
        branch = _git("rev-parse", "--abbrev-ref", "HEAD")
        message = _git("log", "-1", "--format=%s")
        diff_stat = _git("show", "--stat", "--format=", "HEAD")
        files_raw = _git("show", "--name-only", "--format=", "HEAD")
        files = [f for f in files_raw.splitlines() if f.strip()]
        return {
            "sha": sha,
            "branch": branch,
            "message": message,
            "diff_stat": diff_stat[:2000],
            "files_touched": files,
        }
    except Exception as exc:
        return {
            "sha": "unknown",
            "branch": "unknown",
            "message": "",
            "diff_stat": "",
            "files_touched": [],
            "error": str(exc),
        }
